// Client & Worker Shared PDF Templates
const LOGO_IMG = 'data:image/webp;base64,';

const TIMBRO_IMG = 'data:image/png;base64,';

function pdfHeader() {
  return `<!DOCTYPE html>
<html lang="it">
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;400;500;600;700&family=Playfair+Display:wght@600&display=swap" rel="stylesheet">
<style>
  *{box-sizing:border-box;margin:0;padding:0}
  body{font-family:'DM Sans',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#0A0A0A;background:#fff;-webkit-print-color-adjust:exact;print-color-adjust:exact}
  .page{width:794px;max-width:794px;margin:0 auto;padding:34px 46px;min-height:1080px;box-sizing:border-box;display:flex;flex-direction:column;justify-content:space-between;background:#fff}
  .page-main{flex:1 0 auto}
  .hdr{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #004D40;padding-bottom:14px;margin-bottom:18px}
  .brand-logo{height:34px;width:auto;margin-bottom:6px;display:block}
  .brand h1{font-family:'Playfair Display',Georgia,serif;font-size:18px;color:#004D40}
  .brand p{font-size:10.5px;color:#475569;line-height:1.55;margin-top:2px}
  .doc-label{font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:#004D40;text-align:right}
  .doc-meta{font-size:11px;color:#475569;line-height:1.6;text-align:right;margin-top:3px}
  .sec{margin-bottom:16px}
  .sec-title{font-size:10px;font-weight:700;letter-spacing:1.2px;text-transform:uppercase;color:#004D40;margin-bottom:6px}
  .box{background:#F0FDF4;border:1px solid #BBF7D0;border-radius:6px;padding:12px 16px}
  .box-clinic{background:#F8FAFC;border:1px solid #E2E8F0;border-radius:6px;padding:12px 16px;font-size:12px;line-height:1.6;color:#334155}
  table{width:100%;border-collapse:collapse;margin-top:6px}
  thead th{background:#004D40;color:#fff;padding:8px 12px;text-align:left;font-size:11.5px;font-weight:600}
  tbody td{padding:9px 12px;border-bottom:1px solid #E2E8F0;font-size:12px}
  .tot td{font-weight:700;font-size:13px;background:#F1F5F9;padding:11px 12px}
  .tot-num{font-size:18px;color:#004D40;font-family:'Playfair Display',Georgia,serif}
  .regime{font-size:10px;color:#64748B;font-style:italic;margin-top:6px}
  .sconto-box{background:#FFFBEB;border:1px solid #FDE68A;border-radius:6px;padding:10px 14px;margin-top:10px;font-size:11.5px;line-height:1.5;color:#92400E}
  .validity{background:#004D40;color:#fff;border-radius:6px;padding:8px 14px;font-size:11.5px;text-align:center;margin-top:12px}
  .firma-section{margin-top:20px;margin-bottom:6px;display:flex;justify-content:flex-end;break-inside:avoid;page-break-inside:avoid}
  .firma-block{text-align:center;width:200px;break-inside:avoid;page-break-inside:avoid}
  .firma-block .data{font-size:11.5px;margin-bottom:4px;color:#475569}
  .firma-block img{width:145px;max-height:56px;height:auto;object-fit:contain;margin:4px auto;display:block}
  .firma-block .nome{font-size:12.5px;font-weight:600;margin-top:3px;color:#0F172A}
  .firma-block .titolo{font-size:11px;color:#64748B}
  .footer{margin-top:16px;padding-top:10px;border-top:1px solid #E2E8F0;display:flex;justify-content:space-between;font-size:10px;color:#64748B;break-inside:avoid;page-break-inside:avoid}
  .blank{display:inline-block;border-bottom:1px solid #0A0A0A;min-width:200px;margin:0 3px}
  .blank-sm{display:inline-block;border-bottom:1px solid #0A0A0A;min-width:55px;margin:0 3px}
  .body-text{font-size:13.5px;line-height:1.9;margin-bottom:16px;text-align:justify}
  @page{size:A4 portrait;margin:0}
  @media print{
    html,body{width:210mm;height:297mm;margin:0;padding:0;background:#fff !important}
    .page{width:100% !important;max-width:100% !important;min-height:100% !important;padding:24px 36px !important;box-shadow:none !important}
    .firma-section{break-inside:avoid;page-break-inside:avoid}
    .no-print{display:none !important}
  }
</style>`;
}

function pdfBrand(docLabel, docMeta) {
  return `<div class="hdr">
  <div class="brand">
    <img src="${LOGO_IMG}" class="brand-logo" alt="UnghiaIncarnitaStop">
    <p>Studio Podologico Dott. Federico Grassi<br>
    Via Filadelfia 200, 10137 Torino<br>
    Tel. +39 333 421 7550 &nbsp;|&nbsp; P.IVA 10150590015<br>
    podologo.grassi@gmail.com · unghiaincarnitastop.it</p>
  </div>
  <div>
    <div class="doc-label">${docLabel}</div>
    <div class="doc-meta">${docMeta}</div>
  </div>
</div>`;
}

function pdfFirma(dataDoc) {
  return `<div class="firma-section">
  <div class="firma-block">
    <div class="data">Torino, ${dataDoc}</div>
    <img src="${TIMBRO_IMG}" style="width:145px;max-height:56px;height:auto;object-fit:contain;margin:4px auto;display:block;" alt="Timbro Dott. Federico Grassi">
    <div class="nome">Dott. Federico Grassi</div>
    <div class="titolo">Podologo</div>
  </div>
</div>`;
}

function fmtDateLong(iso) {
  if (!iso) return new Date().toLocaleDateString('it-IT', { day: 'numeric', month: 'long', year: 'numeric' });
  return new Date(iso + 'T12:00:00').toLocaleDateString('it-IT', { day: 'numeric', month: 'long', year: 'numeric' });
}

function fmtDate(iso) {
  if (!iso) return new Date().toLocaleDateString('it-IT', { day: '2-digit', month: '2-digit', year: 'numeric' });
  const [y, m, d] = iso.split('-');
  return `${d}/${m}/${y}`;
}

// ─── 1. PREVENTIVO FENOLIZZAZIONE (CLINICA AUREA) ──────────────────────────────

function generatePreventivoHTML(dati) {
  const {
    paziente, trattamento, importo, visitaPagata = 0,
    scontoVisita = false, descrizione, data, numero,
    ditaSede, dueSeduteSeparate,
  } = dati;

  const nomiTrattamento = {
    mono:        'Fenolizzazione Monolaterale Lamina',
    bi:          'Fenolizzazione Bilaterale Lamina',
    '2dita_mono':'Fenolizzazione 2 Dita — Monolaterale',
    '2dita_bi':  'Fenolizzazione 2 Dita — Bilaterale',
  };

  const nomeTratt          = nomiTrattamento[trattamento] || trattamento;
  const imp                = Number(importo);
  const costoAnestesista   = 150;
  const costoSala          = 100;
  const quotaFenolizzazione = Math.max(0, imp - (costoAnestesista + costoSala));
  const visita             = Number(visitaPagata);
  const netto              = scontoVisita && visita > 0 ? Math.max(0, imp - visita) : imp;
  const dataDoc            = fmtDateLong(data);
  const num                = numero || 'P-' + new Date().getFullYear() + '-' + Date.now().toString().slice(-4);
  const isBilateraleDueDita = Boolean(dueSeduteSeparate || trattamento === '2dita_bi');

  return pdfHeader() + `<title>Preventivo ${num} — UnghiaIncarnitaStop</title></head><body>
<div class="page">
  ${pdfBrand('PREVENTIVO TRATTAMENTO FENOLIZZAZIONE', `N° ${num}<br>Data: ${dataDoc}<br>Validità: 30 giorni`)}

  <div class="sec">
    <div class="sec-title">Paziente</div>
    <div class="box">
      <div style="font-size:16px;font-weight:700;margin-bottom:4px;color:#0F172A">${paziente.nome || paziente}</div>
      ${paziente.email    ? `<div style="font-size:12px;color:#475569">Email: ${paziente.email}</div>` : ''}
      ${paziente.telefono ? `<div style="font-size:12px;color:#475569">Telefono: ${paziente.telefono}</div>` : ''}
      ${ditaSede ? `<div style="font-size:12px;color:#0F172A;margin-top:4px;">Sede anatomica obiettiva: <strong>${ditaSede}</strong></div>` : ''}
    </div>
  </div>

  <div class="sec">
    <div class="sec-title">Composizione Preventivo & Voci Economiche</div>
    <table>
      <thead>
        <tr>
          <th>Voce / Prestazione</th>
          <th style="text-align:center;width:45px;">Q.tà</th>
          <th style="text-align:right;width:110px;">Importo</th>
        </tr>
      </thead>
      <tbody>
        <tr>
          <td>
            <strong>Trattamento di fenolizzazione</strong> (${nomeTratt})
            ${ditaSede ? `<br><span style="font-size:11.5px;color:#475569">Localizzazione: <strong>${ditaSede}</strong></span>` : ''}
            <br><span style="font-size:11.5px;color:#475569">Matricectomia chimica mediante fenolo e controlli post-operatori fino a guarigione</span>
            ${descrizione ? `<br><span style="font-size:11.5px;color:#475569">${descrizione}</span>` : ''}
          </td>
          <td style="text-align:center">1</td>
          <td style="text-align:right;font-family:'DM Sans',sans-serif;font-weight:600">€ ${quotaFenolizzazione.toFixed(2)}</td>
        </tr>
        <tr>
          <td>
            <strong>Anestesista</strong>
            <br><span style="font-size:11.5px;color:#475569">Assistenza e monitoraggio clinico anestesiologico specialistico dedicato</span>
          </td>
          <td style="text-align:center">1</td>
          <td style="text-align:right;font-family:'DM Sans',sans-serif;font-weight:600">€ ${costoAnestesista.toFixed(2)}</td>
        </tr>
        <tr>
          <td>
            <strong>Sala chirurgica</strong>
            <br><span style="font-size:11.5px;color:#475569">Struttura autorizzata e strumentario sterile (Clinica Aurea — Via Pietro Palmieri 50, Torino)</span>
          </td>
          <td style="text-align:center">1</td>
          <td style="text-align:right;font-family:'DM Sans',sans-serif;font-weight:600">€ ${costoSala.toFixed(2)}</td>
        </tr>
        <tr style="background:#F8FAFC;border-top:1px solid #CBD5E1;">
          <td colspan="2" style="font-weight:600;color:#0F172A">
            Totale complessivo trattamento
          </td>
          <td style="text-align:right;font-weight:700">€ ${imp.toFixed(2)}</td>
        </tr>
        ${scontoVisita && visita > 0 ? `
        <tr>
          <td colspan="2" style="color:#065F46;font-size:12.5px;background:#ECFDF5">
            <strong>Deduzione prima visita sostenuta (se prenotato entro 30 giorni)</strong>
          </td>
          <td style="text-align:right;color:#065F46;font-weight:700;background:#ECFDF5">− € ${visita.toFixed(2)}</td>
        </tr>` : ''}
      </tbody>
      <tfoot>
        <tr class="tot">
          <td colspan="2">
            <strong>TOTALE SALDO NETTO EFFETTIVO</strong><br>
            <span style="font-size:11px;font-weight:400;color:#64748B">
              Regime forfettario – esente IVA (art. 1, c. 54-89, L. 190/2014)
            </span>
          </td>
          <td style="text-align:right"><span class="tot-num">€ ${netto.toFixed(2)}</span></td>
        </tr>
      </tfoot>
    </table>
    <p class="regime">* Operando in regime forfettario, la prestazione non è soggetta ad IVA.</p>

    ${isBilateraleDueDita ? `
    <div style="margin-top:14px;padding:12px 14px;background:#FFFBEB;border:1px solid #F59E0B;border-radius:6px;font-size:12px;color:#92400E;line-height:1.5;">
      <strong>Programmazione Clinica (2 Sedute Separate):</strong><br>
      Trattandosi di onicocriptosi bilaterale interessante due dita distinte, i trattamenti sono normalmente programmati in <strong>due sedute operatorie differenti</strong> al fine di garantire la deambulazione e il decorso post-operatorio ottimale del paziente, salvo diversa indicazione esplicita del professionista.
    </div>` : ''}

    ${scontoVisita && visita > 0 ? `
    <div class="sconto-box">
      <strong>Nota Sconto Applicato:</strong> L'importo della prima visita sostenuta (€ ${visita.toFixed(2)})
      viene interamente scomputato dall'importo del trattamento se l'operazione viene prenotata entro 30 giorni dalla data odierna (${dataDoc}).
    </div>` : ''}
  </div>

  <div class="sec">
    <div class="sec-title">Sede dell'Intervento & Istruzioni per la Prenotazione</div>
    <div class="box-clinic">
      L'intervento di fenolizzazione della lamina ungueale verrà eseguito presso:<br>
      <strong>Clinica Aurea — Via Pietro Palmieri, 50, 10138 Torino (TO)</strong>.<br><br>
      Include: anestesia locale specialistica, matricectomia chimica mediante fenolo, medicazione locale e controlli post-operatori fino a guarigione.<br><br>
      Per prenotare l'intervento e compilare il modulo di consenso informato obbligatorio prima dell'intervento, utilizzare il link:<br>
      <strong>https://calendly.com/federico-grassi-unghiaincarnitastop/trattamento-per-unghia-incarnita-aurea</strong>
    </div>
  </div>

  ${pdfFirma(dataDoc)}

  <div class="footer">
    <div><strong>UnghiaIncarnitaStop</strong> · Clinica Aurea, Via Pietro Palmieri 50, Torino</div>
    <div>Dott. Federico Grassi — Tel. +39 333 421 7550</div>
  </div>
</div>
</body></html>`;
}

// ─── 2. RICEVUTA SANITARIA VISITA ──────────────────────────────────────────────

