// ─── PIPELINE PDF UNICA CLIENT-SIDE (html2pdf.js locale, rendering isolato) ────
//
// Il documento HTML completo (con <head>/<style>) viene renderizzato dentro un
// <iframe srcdoc> dedicato: gli stili del gestionale non toccano il documento e
// gli stili del documento non toccano il gestionale. html2pdf viene caricato
// DENTRO l'iframe dalla copia locale (assets/vendor, identica alla 0.10.1 CDN).
// Il risultato è un unico binario PDF validato, riusabile per anteprima,
// download, stampa e allegato email.

const HTML2PDF_LOCAL_URL = new URL('../assets/vendor/html2pdf.bundle.min.js', import.meta.url).href;
const PDF_PAGE_WIDTH_PX = 794;   // A4 a 96dpi
const PDF_PAGE_HEIGHT_PX = 1123; // A4 a 96dpi

function pdfWait(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function pdfWithTimeout(promise, ms) {
  return Promise.race([promise, pdfWait(ms)]);
}

function pdfBytesToBase64(bytes) {
  let binary = '';
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunk));
  }
  return btoa(binary);
}

function pdfValidateBytes(bytes) {
  if (!bytes || bytes.length < 1024) {
    throw new Error('Il PDF generato è vuoto o incompleto.');
  }
  const head = String.fromCharCode.apply(null, bytes.subarray(0, 5));
  if (head !== '%PDF-') {
    throw new Error('Il file generato non è un PDF valido.');
  }
  const tail = String.fromCharCode.apply(null, bytes.subarray(Math.max(0, bytes.length - 2048)));
  if (!tail.includes('%%EOF')) {
    throw new Error('Il PDF generato risulta troncato.');
  }
}

// Conta i pixel "non bianchi" di una porzione del canvas renderizzato (campionamento ridotto)
function pdfInkRatio(canvas, y, h) {
  const sw = 120;
  const sh = Math.max(1, Math.round(sw * h / canvas.width));
  const probe = document.createElement('canvas');
  probe.width = sw;
  probe.height = sh;
  const ctx = probe.getContext('2d');
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, sw, sh);
  ctx.drawImage(canvas, 0, y, canvas.width, h, 0, 0, sw, sh);
  const data = ctx.getImageData(0, 0, sw, sh).data;
  let ink = 0;
  for (let i = 0; i < data.length; i += 4) {
    if (data[i] < 235 || data[i + 1] < 235 || data[i + 2] < 235) ink++;
  }
  return ink / (sw * sh);
}

function pdfBuildIsolatedDocument(htmlContent) {
  let docHtml = String(htmlContent);
  if (!/<html[\s>]/i.test(docHtml)) {
    docHtml = `<!DOCTYPE html><html lang="it"><head><meta charset="UTF-8"></head><body>${docHtml}</body></html>`;
  }
  // Lo script va messo PRIMA di qualunque <link> esterno (es. Google Fonts),
  // così il caricamento della libreria non viene bloccato da fogli di stile remoti.
  const scriptTag = `<script src="${HTML2PDF_LOCAL_URL}" onerror="window.__html2pdfLoadError=true"><\/script>`;
  if (/<head[^>]*>/i.test(docHtml)) {
    docHtml = docHtml.replace(/<head[^>]*>/i, match => match + scriptTag);
  } else {
    docHtml = docHtml.replace(/<html[^>]*>/i, match => match + '<head>' + scriptTag + '</head>');
  }
  // Garantisce sfondo bianco e assenza di margini nel documento isolato
  return docHtml.replace(/<\/head>/i, '<style>html,body{margin:0;padding:0;background:#fff}</style></head>');
}

/**
 * Genera UNA volta il PDF del documento e restituisce lo stesso binario in più forme.
 * @returns {Promise<{bytes:Uint8Array, blob:Blob, base64:string, pageCount:number, filename:string, size:number}>}
 */
async function generatePdfDocument(htmlContent, filename = 'documento.pdf') {
  if (typeof window === 'undefined' || typeof document === 'undefined') {
    throw new Error('Ambiente browser non disponibile per la generazione del PDF.');
  }
  if (!htmlContent || typeof htmlContent !== 'string') {
    throw new Error('Contenuto del documento mancante: impossibile generare il PDF.');
  }

  const iframe = document.createElement('iframe');
  iframe.setAttribute('aria-hidden', 'true');
  iframe.tabIndex = -1;
  iframe.style.cssText = `position:fixed;left:0;top:0;opacity:0;z-index:-1;width:${PDF_PAGE_WIDTH_PX}px;height:${PDF_PAGE_HEIGHT_PX}px;border:0;pointer-events:none;`;
  iframe.srcdoc = pdfBuildIsolatedDocument(htmlContent);
  document.body.appendChild(iframe);

  try {
    // 1. Attende documento isolato pronto + libreria locale caricata (max 15s)
    const started = Date.now();
    let win, doc;
    for (;;) {
      win = iframe.contentWindow;
      doc = iframe.contentDocument;
      if (win && win.__html2pdfLoadError) {
        throw new Error('Libreria PDF locale non trovata (assets/vendor/html2pdf.bundle.min.js).');
      }
      if (win && doc && typeof win.html2pdf === 'function' && doc.readyState !== 'loading' && doc.body) break;
      if (Date.now() - started > 15000) {
        throw new Error('Timeout nella preparazione del documento PDF. Riprova.');
      }
      await pdfWait(50);
    }

    // 2. Immagini (logo + timbro base64): devono essere realmente caricate
    const images = Array.from(doc.images);
    await Promise.all(images.map(img => (img.complete ? null : new Promise(res => { img.onload = res; img.onerror = res; }))));
    const broken = images.filter(img => !img.naturalWidth);
    if (broken.length) {
      throw new Error('Logo o timbro non caricati correttamente: PDF non generato.');
    }
    await Promise.all(images.map(img => (img.decode ? img.decode().catch(() => {}) : null)));

    // 3. Font web: best effort (max ~3s), altrimenti si usano i font di sistema del template
    const links = Array.from(doc.querySelectorAll('link[rel="stylesheet"]'));
    await pdfWithTimeout(Promise.all(links.map(l => (l.sheet ? null : new Promise(res => { l.onload = res; l.onerror = res; })))), 2000);
    if (doc.fonts && doc.fonts.ready) await pdfWithTimeout(doc.fonts.ready, 1500);
    await pdfWait(50);

    // 4. Rendering con html2pdf eseguito DENTRO l'iframe isolato
    const element = doc.querySelector('.page') || doc.body;
    const opt = {
      margin: 0,
      filename,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: {
        scale: 2,
        useCORS: true,
        logging: false,
        backgroundColor: '#ffffff',
        scrollX: 0,
        scrollY: 0,
        windowWidth: PDF_PAGE_WIDTH_PX,
        width: PDF_PAGE_WIDTH_PX,
        windowHeight: element.scrollHeight
      },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait', compress: true },
      pagebreak: { mode: ['css', 'legacy'] }
    };

    const worker = win.html2pdf().set(opt).from(element).toPdf();
    const pdf = await worker.get('pdf');
    const canvas = await worker.get('canvas');
    if (!pdf || !canvas || !canvas.width || !canvas.height) {
      throw new Error('Rendering del documento non riuscito.');
    }

    // 5. Controllo pagine bianche (documento intero e ultima pagina)
    const pageCount = pdf.internal.getNumberOfPages();
    if (pdfInkRatio(canvas, 0, canvas.height) < 0.002) {
      throw new Error('Il PDF generato risulta bianco: invio/visualizzazione bloccati.');
    }
    const pxPerPage = Math.floor(canvas.width * (297 / 210));
    const lastStart = (pageCount - 1) * pxPerPage;
    if (pageCount > 1 && lastStart < canvas.height &&
        pdfInkRatio(canvas, lastStart, canvas.height - lastStart) < 0.0005) {
      throw new Error('Il PDF generato contiene una pagina finale vuota.');
    }

    // 6. Binario finale (copiato nel contesto principale) + validazione
    const raw = new Uint8Array(pdf.output('arraybuffer'));
    const bytes = new Uint8Array(raw.length);
    bytes.set(raw);
    pdfValidateBytes(bytes);

    const base64 = pdfBytesToBase64(bytes);
    if (!base64.startsWith('JVBERi')) {
      throw new Error('Codifica Base64 del PDF non valida.');
    }

    return {
      bytes,
      blob: new Blob([bytes], { type: 'application/pdf' }),
      base64,
      pageCount,
      filename,
      size: bytes.length
    };
  } finally {
    if (iframe.parentNode) iframe.parentNode.removeChild(iframe);
  }
}

// Compatibilità: stessa firma di prima, ora basata sulla pipeline unica validata.
async function convertHtmlToPdfBase64(htmlContent, filename = 'documento.pdf') {
  const result = await generatePdfDocument(htmlContent, filename);
  return result.base64;
}

