// ─── 9. CARTELLA CLINICA ONICOCRIPTOSI ─────────────────────────────────────────

function generateCartellaClinicaHTML(dati) {
  const { paziente = {}, cartella = {}, dataNascita = '', percorso = '', sedeTesto = '' } = dati;
  const esc = v => String(v ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
  const sn = v => v === 1 ? '<strong style="color:#004D40">Sì</strong>' : v === 0 ? 'No' : '<span style="color:#94A3B8">—</span>';
  const cella = (k, v) => `<td style="width:25%;color:#64748B;font-size:11px">${k}</td><td style="width:25%;font-size:12px">${v}</td>`;
  const testo = v => v
    ? String(v).split('\n').map(r => `<div style="page-break-inside:avoid;break-inside:avoid;min-height:1.2em">${esc(r)}</div>`).join('')
    : '<span style="color:#94A3B8">Non compilato</span>';
  const nomeCompleto = esc(`${paziente.nome || ''} ${paziente.cognome || ''}`.trim() || 'Paziente');
  const indirizzo = [paziente.indirizzo, paziente.citta].filter(Boolean).join(', ');
  const fmtTs = ts => {
    if (!ts) return '';
    const d = new Date(String(ts).replace(' ', 'T') + 'Z');
    return isNaN(d) ? esc(ts) : d.toLocaleString('it-IT', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
  };
  const dataVisita = fmtDate(cartella.data_visita);
  const dataDoc = fmtDateLong(cartella.data_visita);
  const versione = cartella.versione || 1;
  const datiRiga = (k, v) => v ? `<div>${k}: <strong style="color:#0F172A">${esc(v)}</strong></div>` : '';

  return pdfHeader() + `<title>Cartella Clinica — ${nomeCompleto}</title></head><body>
<div class="page">
  <div class="page-main">
  ${pdfBrand('CARTELLA CLINICA ONICOCRIPTOSI', `Data visita: ${dataVisita}<br>Versione ${versione} · agg. ${fmtTs(cartella.modificato_il)}`)}

  <div class="sec">
    <div class="sec-title">Dati Paziente</div>
    <div class="box">
      <div style="font-size:16px;font-weight:700;color:#0F172A;margin-bottom:4px">${nomeCompleto}</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:2px 20px;font-size:11.5px;color:#475569">
        ${datiRiga('Nato/a il', dataNascita)}
        ${datiRiga('C.F.', paziente.codice_fiscale)}
        ${paziente.telefono ? `<div>Tel: ${esc(paziente.telefono)}</div>` : ''}
        ${paziente.email ? `<div>Email: ${esc(paziente.email)}</div>` : ''}
        ${indirizzo ? `<div>Indirizzo: ${esc(indirizzo)}</div>` : ''}
        ${percorso ? `<div>Percorso: ${esc(percorso)}</div>` : ''}
      </div>
    </div>
  </div>

  <div class="sec">
    <div class="sec-title">Sede</div>
    <div class="box-clinic">${sedeTesto ? esc(sedeTesto) : '<span style="color:#94A3B8">Non specificata</span>'}</div>
  </div>

  <div class="sec">
    <div class="sec-title">Valutazione Clinica</div>
    <table style="margin-top:0;border:1px solid #E2E8F0">
      <tbody>
        <tr>${cella('Granuloma', sn(cartella.granuloma))}${cella('Infiammazione', sn(cartella.infiammazione))}</tr>
        <tr>${cella('Infezione', sn(cartella.infezione))}${cella('Secrezione', sn(cartella.secrezione))}</tr>
        <tr>${cella('Dolore (0–10)', cartella.dolore === null || cartella.dolore === undefined ? '<span style="color:#94A3B8">—</span>' : `<strong>${esc(cartella.dolore)}</strong> / 10`)}${cella('Stadio onicocriptosi', cartella.stadio ? `<strong>${esc(cartella.stadio)}</strong>` : '<span style="color:#94A3B8">—</span>')}</tr>
      </tbody>
    </table>
  </div>

  ${cartella.motivo_paziente ? `
  <div class="sec">
    <div class="sec-title">Motivo / note riferite dal paziente</div>
    <div style="border:1px dashed #CBD5E1;border-radius:6px;padding:9px 14px;font-size:11.5px;color:#64748B;font-style:italic;white-space:pre-wrap">"${esc(cartella.motivo_paziente)}" <span style="font-style:normal">(da prenotazione online — non è una valutazione clinica)</span></div>
  </div>` : ''}

  <div class="sec">
    <div class="sec-title">Anamnesi Essenziale</div>
    <div class="box-clinic" style="white-space:pre-wrap">${testo(cartella.anamnesi)}</div>
  </div>

  <div class="sec">
    <div class="sec-title">Trattamento Effettuato</div>
    <div class="box-clinic" style="white-space:pre-wrap">${testo(cartella.trattamento)}</div>
  </div>

  <div class="sec">
    <div class="sec-title">Note Cliniche</div>
    <div class="box-clinic" style="white-space:pre-wrap">${testo(cartella.note)}</div>
  </div>
  </div>

  ${pdfFirma(dataDoc)}

  <div class="footer">
    <div><strong>Studio Podologico Dott. Federico Grassi</strong> · Via Filadelfia 200, Torino</div>
    <div>Cartella n. ${esc(cartella.id || '—')} · versione ${versione}${cartella.modificato_da ? ' · ' + esc(cartella.modificato_da) : ''}</div>
  </div>
</div>
</body></html>`;
}

export {
  LOGO_IMG,
  TIMBRO_IMG,
  generatePreventivoHTML,
  generateRicevutaHTML,
  generateAttestoPresenzaHTML,
  generateAttestoSportHTML,
  generateLetteraDimissioniHTML,
  TERAPIA_DIMISSIONI_DEFAULT,
  generateBozzaFatturaHTML,
  generateCartellaClinicaHTML,
  convertHtmlToPdfBase64,
  generatePdfDocument,
  generateEmailCoverHTML
};


